INSERT INTO public.review_categories VALUES ('735e6d82-6d74-438b-98ad-10c7ecc70df6', 'checkout_issues', 'Checkout issues', 'Problems during checkout or payment: errors, declined or failed payments, a confusing or broken checkout flow.', true, 1, '2026-08-16 13:35:56.572087+00', '2026-08-16 13:35:56.572087+00');
INSERT INTO public.review_categories VALUES ('fd2edae3-0662-49ec-b34f-488f15eb380e', 'wrong_product', 'Wrong product', 'The customer received the wrong item, variant, size, or colour compared to what they ordered.', true, 2, '2026-08-16 13:35:56.572087+00', '2026-08-16 13:35:56.572087+00');
INSERT INTO public.review_categories VALUES ('4b701d22-d55a-4c18-bd42-8095d81b582a', 'product_broken', 'Product broken', 'The product arrived damaged, defective, or broken, stopped working, or was poor quality.', true, 3, '2026-08-16 13:35:56.572087+00', '2026-08-16 13:35:56.572087+00');
INSERT INTO public.review_categories VALUES ('bc2189a8-8ed6-4677-87f0-580c99833de7', 'late_shipment', 'Late shipment', 'Shipping or delivery problems: the order arrived late, shipping was slow, or delivery was delayed.', true, 4, '2026-08-16 13:35:56.572087+00', '2026-08-16 13:35:56.572087+00');
INSERT INTO public.review_categories VALUES ('21ca5a74-4fb0-4d83-b1fa-bcccafd26cd4', 'slow_website', 'Slow website', 'Complaints that the website or app is slow, laggy, unresponsive, or has technical glitches.', true, 5, '2026-08-16 13:35:56.572087+00', '2026-08-16 13:35:56.572087+00');
INSERT INTO public.review_categories VALUES ('9440bc99-b593-457d-b66b-853e1c843177', 'happy_customer', 'Happy customer', 'Positive feedback: the customer is satisfied and happy with the product or their experience.', true, 6, '2026-08-16 13:35:56.572087+00', '2026-08-16 13:35:56.572087+00');


